package com.unicare.dispensary.screening;import jakarta.validation.Valid;import java.security.Principal;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController public class ScreeningController{private final ScreeningService service;public ScreeningController(ScreeningService s){service=s;}@GetMapping("/api/screening/my")public List<ScreeningResponse> mine(Principal p){return service.mine(p.getName());}@PostMapping("/api/screening")@ResponseStatus(HttpStatus.CREATED)public ScreeningResponse create(@Valid @RequestBody ScreeningRequest r,Principal p){return service.create(p.getName(),r);}@GetMapping("/api/staff/screenings")public List<ScreeningResponse> all(){return service.all();}}
